function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const id = encodeURIComponent(String(input.backtest_id || '').trim())
  if (!id) throw new Error('backtest_id is required')
  const response = await fetch(apiOrigin() + '/api/backtests/' + id, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  const payload = await response.json()
  const snapshot = payload.provenance?.strategy_python
  const sourceAvailable = typeof snapshot?.source === 'string'
  const includePythonSource = input.include_python_source === true
  if (sourceAvailable && !includePythonSource) payload.provenance.strategy_python = { sha256: snapshot.sha256 }
  return { ...payload, python_source_available: sourceAvailable, python_source_included: sourceAvailable && includePythonSource }
}
